let currentCity=cities[0],weather=null,requestId=0,map,marker,radarLayer,coverageLayer,modelGroup,mode='radar',frames=[],radarHost='',frameIndex=0,playing=null,gridData=[],weatherBusy=false,radarBusy=false,gridBusy=false,radarTileErrors=0;
const cache=new Map();
const fmt=(n,d=0)=>Number.isFinite(n)?n.toFixed(d):'—';
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function timeLabel(s){return new Date(typeof s==='number'?s*1000:s.endsWith('Z')?s:s+'+07:00').toLocaleTimeString('th-TH',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit'});}
function clock(){const d=new Date();$('dateLabel').textContent=d.toLocaleDateString('th-TH',{timeZone:'Asia/Bangkok',weekday:'long',day:'numeric',month:'long',year:'numeric'});$('clockLabel').textContent=d.toLocaleTimeString('th-TH',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit'})+' น. · เวลาไทย UTC+7';}
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,5500);}
function desc(c){if(c===0)return'ท้องฟ้าแจ่มใส';if(c===1)return'มีเมฆเล็กน้อย';if(c===2)return'มีเมฆบางส่วน';if(c===3)return'มีเมฆมาก';if(c>=45&&c<=48)return'หมอก';if(c>=51&&c<=57)return'ฝนปรอย';if(c>=61&&c<=67)return c>=65?'ฝนตกหนัก':'ฝนตก';if(c>=71&&c<=77)return'หิมะ';if(c>=80&&c<=82)return'ฝนตกเป็นแห่ง ๆ';if(c>=95)return'ฝนฟ้าคะนอง';return'ไม่มีข้อมูล';}
function icon(c){let p='';if(c===0)p='<circle cx="24" cy="24" r="9"/><path d="M24 4v5m0 30v5M4 24h5m30 0h5M10 10l4 4m20 20 4 4M10 38l4-4m20-20 4-4"/>';else{if(c<3)p='<circle cx="17" cy="16" r="8"/><path d="M17 3v3M4 16h3M7 6l3 3m17-3-3 3"/>';p+='<path d="M12 33a8 8 0 0 1-1-16 11 11 0 0 1 20-1 9 9 0 1 1 4 17Z"/>';if(c>=51)p+='<path d="m15 38-2 5m11-5-2 5m11-5-2 5"/>';if(c>=95)p+='<path d="m26 29-6 9h6l-4 9"/>';}return`<svg class="weather-svg" viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p}</svg>`;}
function direction(d){return Number.isFinite(d)?['เหนือ','ตะวันออกเฉียงเหนือ','ตะวันออก','ตะวันออกเฉียงใต้','ใต้','ตะวันตกเฉียงใต้','ตะวันตก','ตะวันตกเฉียงเหนือ'][Math.round(d/45)%8]:'—';}
async function getJSON(url,ttl=0){const item=cache.get(url);if(item&&Date.now()-item.time<ttl)return item.data;const ac=new AbortController(),timer=setTimeout(()=>ac.abort(),18000);try{const r=await fetch(url,{signal:ac.signal});if(!r.ok)throw Error('HTTP '+r.status);const data=await r.json();if(data.error)throw Error(data.reason||'API error');cache.set(url,{time:Date.now(),data});return data;}finally{clearTimeout(timer);}}
function forecastURL(city){const p=new URLSearchParams({latitude:city[1],longitude:city[2],current:'temperature_2m,relative_humidity_2m,apparent_temperature,is_day,precipitation,weather_code,cloud_cover,pressure_msl,wind_speed_10m,wind_direction_10m,wind_gusts_10m,dew_point_2m,visibility',hourly:'temperature_2m,apparent_temperature,precipitation_probability,precipitation,weather_code,wind_speed_10m,wind_gusts_10m,wind_direction_10m,relative_humidity_2m,pressure_msl,cloud_cover,visibility,dew_point_2m',daily:'weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,precipitation_sum,wind_speed_10m_max,wind_gusts_10m_max,sunrise,sunset,uv_index_max',timezone:'Asia/Bangkok',forecast_days:7});return'https://api.open-meteo.com/v1/forecast?'+p;}
function loadingWeather(){weather=null;resetDetails();$('weatherState').textContent='กำลังโหลด';['temperature','feelsLike','humidity','windValue','rainValue','pressureValue'].forEach(id=>$(id).textContent='—');$('weatherDescription').textContent='กำลังเชื่อมต่อข้อมูลอากาศ…';$('weatherIcon').innerHTML=icon(3);$('weatherTime').textContent='Open-Meteo · รอข้อมูล';$('hourlyForecast').innerHTML='<div class="loading-text">กำลังโหลดพยากรณ์…</div>';$('dailyForecast').innerHTML='<div class="loading-text">กำลังโหลดพยากรณ์ 7 วัน…</div>';}
async function loadWeather(clear=true){const id=++requestId,city=[...currentCity];if(clear)loadingWeather();weatherBusy=true;$('connectionStatus').textContent='กำลังตรวจสอบข้อมูล';try{const d=await getJSON(forecastURL(city),14*60000);if(id!==requestId)return;if(!d.current||!d.hourly||!d.daily)throw Error('Missing forecast');weather=d;renderWeather(d);$('connectionStatus').textContent='เชื่อมต่อ Open-Meteo สำเร็จ';}catch(e){if(id!==requestId)return;detailError(!!weather);$('weatherState').textContent=weather?'ข้อมูลเดิม':'โหลดไม่สำเร็จ';$('connectionStatus').textContent='เชื่อมต่อไม่ได้ · กด ↻ เพื่อลองใหม่';if(weather){$('weatherTime').textContent+=' · อัปเดตไม่สำเร็จ';}else{$('weatherDescription').textContent='ยังไม่สามารถโหลดข้อมูลได้';$('hourlyForecast').innerHTML='<div class="loading-text">ไม่สามารถเชื่อมต่อ Open-Meteo</div>';$('dailyForecast').innerHTML='<div class="loading-text">ยังไม่มีข้อมูลพยากรณ์ · ลองโหลดใหม่อีกครั้ง</div>';}}finally{if(id===requestId)weatherBusy=false;}}
function renderWeather(d){const c=d.current;$('temperature').textContent=fmt(c.temperature_2m);$('feelsLike').textContent=fmt(c.apparent_temperature);$('humidity').textContent=fmt(c.relative_humidity_2m);$('windValue').textContent=fmt(c.wind_speed_10m,1);$('windDirection').textContent='กม./ชม. · จาก'+direction(c.wind_direction_10m);$('rainValue').textContent=fmt(c.precipitation,1);$('pressureValue').textContent=fmt(c.pressure_msl);$('weatherDescription').textContent=desc(c.weather_code);$('weatherIcon').innerHTML=icon(c.weather_code);$('weatherState').textContent=Date.now()-new Date(c.time+'+07:00').getTime()>90*60000?'ข้อมูลล่าช้า':'ข้อมูลล่าสุด';$('weatherTime').textContent='Open-Meteo · ข้อมูล '+timeLabel(c.time)+' น. (เวลาไทย)';let start=d.hourly.time.findIndex(t=>new Date(t+'+07:00').getTime()>=Date.now());if(start<0)start=0;const samples=[0,6,12,23].map(x=>Math.min(start+x,d.hourly.time.length-1));$('hourlyForecast').innerHTML=samples.map(i=>`<div class="hour-item"><span>${timeLabel(d.hourly.time[i])}</span>${icon(d.hourly.weather_code[i])}<strong>${fmt(d.hourly.temperature_2m[i])}°</strong><small>♧ ${fmt(d.hourly.precipitation_probability[i])}%</small></div>`).join('');$('dailyForecast').innerHTML=d.daily.time.map((t,i)=>{const date=new Date(t+'T12:00:00+07:00'),prob=d.daily.precipitation_probability_max[i];return`<article class="day-card" data-day="${t}" tabindex="0" role="button" aria-label="ดูพยากรณ์รายชั่วโมงวันที่ ${t}"><div class="day-top"><h3>${i===0?'วันนี้':date.toLocaleDateString('th-TH',{timeZone:'Asia/Bangkok',weekday:'short'})}</h3><span class="day-date">${date.toLocaleDateString('th-TH',{timeZone:'Asia/Bangkok',day:'numeric',month:'short'})}</span></div>${icon(d.daily.weather_code[i])}<div class="day-temps">${fmt(d.daily.temperature_2m_max[i])}°<span>${fmt(d.daily.temperature_2m_min[i])}°</span></div><div class="day-desc">${desc(d.daily.weather_code[i])}</div><div class="rain-bar"><i style="width:${Number.isFinite(prob)?prob:0}%"></i></div><div class="day-rain"><span>โอกาสฝน</span><b>${fmt(prob)}%</b></div><div class="day-detail"><span>ฝน ${fmt(d.daily.precipitation_sum[i],1)} มม.</span><span>กระโชก ${fmt(d.daily.wind_gusts_10m_max?.[i])} กม./ชม.</span><span>UV สูงสุด ${fmt(d.daily.uv_index_max?.[i],1)}</span></div></article>`;}).join('');renderWeatherDetails(d);}
function selectCity(city,pan=true){pointRequested=true;selectedDay='next';currentCity=city;$('locationName').textContent=city[0];$('forecastLocation').textContent=city[0];$('coordinates').textContent=city[1].toFixed(3)+'° N, '+city[2].toFixed(3)+'° E';$('searchResults').hidden=true;$('citySearch').value='';document.querySelectorAll('[data-city]').forEach(b=>b.classList.toggle('selected',cities[+b.dataset.city][0]===city[0]));if(map){marker.closePopup();marker.unbindPopup();marker.setLatLng([city[1],city[2]]);marker.bindTooltip(escapeHTML(city[0]),{direction:'top',offset:[0,-9]});if(pan)map.flyTo([city[1],city[2]],Math.max(map.getZoom(),11),{duration:.7});}loadWeather();}
function initMap(){if(!window.L){$('mapError').hidden=false;$('mapError').textContent='โหลดแผนที่ไม่สำเร็จ กรุณารีเฟรชหน้าเว็บ';return;}map=L.map('map',{zoomControl:false,scrollWheelZoom:true,minZoom:4,maxZoom:18,maxBounds:[[0,85],[29,117]],maxBoundsViscosity:.8}).setView([14.1,101.2],6);const base=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,referrerPolicy:'strict-origin-when-cross-origin',attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);let baseErrors=0;base.on('loading',()=>{baseErrors=0;});base.on('tileerror',()=>{baseErrors++;$('baseMapError').hidden=false;$('baseMapError').textContent='โหลดแผนที่พื้นหลังบางส่วนไม่สำเร็จ กรุณาลองรีเฟรชหน้าเว็บ';});base.on('load',()=>{$('baseMapError').hidden=baseErrors===0;});marker=L.marker([currentCity[1],currentCity[2]],{icon:L.divIcon({html:'<div class="selected-pin"></div>',className:'',iconSize:[16,16],iconAnchor:[8,8]}),zIndexOffset:1000}).addTo(map).bindTooltip(currentCity[0],{direction:'top',offset:[0,-9]});modelGroup=L.layerGroup();L.control.scale({imperial:false,position:'bottomleft'}).addTo(map);map.on('zoomend',updateMapResolution);map.on('moveend',()=>{if(areaGrid){$('resolutionNote').textContent='จุดตัวอย่างเดิมยังคงแสดงอยู่ · กดอ่านค่า 9 จุดเพื่ออัปเดตบริเวณที่กำลังดู';}});updateMapResolution();map.on('click',e=>{if(e.latlng.lat<5.5||e.latlng.lat>21||e.latlng.lng<97||e.latlng.lng>106){toast('เลือกจุดในประเทศไทยหรือพื้นที่ใกล้เคียง');return;}const close=cities.reduce((a,b)=>Math.hypot(b[1]-e.latlng.lat,b[2]-e.latlng.lng)<Math.hypot(a[1]-e.latlng.lat,a[2]-e.latlng.lng)?b:a);const isClose=Math.hypot(close[1]-e.latlng.lat,close[2]-e.latlng.lng)<.15;selectCity([isClose?close[0]:'พื้นที่ที่เลือก',e.latlng.lat,e.latlng.lng],false);});}
function stopPlay(){if(playing)clearInterval(playing);playing=null;$('playBtn').textContent='▶';$('playBtn').setAttribute('aria-label','เล่นภาพเรดาร์ย้อนหลัง');}
function displayFrame(index){if(!map||!frames.length)return;frameIndex=+index;const f=frames[frameIndex];$('timeSlider').value=frameIndex;$('frameTime').textContent=new Date(f.time*1000).toLocaleDateString('th-TH',{timeZone:'Asia/Bangkok',day:'numeric',month:'short'})+' '+timeLabel(f.time)+' น. · '+(frameIndex===frames.length-1?'ภาพล่าสุด':'ย้อนหลัง');if(mode!=='radar')return;const url=radarHost+f.path+'/256/{z}/{x}/{y}/2/'+($('smoothRadar').checked?'1':'0')+'_0.png';radarTileErrors=0;if(radarLayer){radarLayer.setUrl(url);if(!map.hasLayer(radarLayer))radarLayer.addTo(map);}else{radarLayer=L.tileLayer(url,{opacity:radarOpacity,maxNativeZoom:7,maxZoom:18,zIndex:200,attribution:'Weather data by <a href="https://www.rainviewer.com/">RainViewer</a>'}).addTo(map);radarLayer.on('tileerror',()=>{if(++radarTileErrors>=3){$('mapStatus').textContent='โหลดภาพเรดาร์ไม่สำเร็จ';$('mapError').textContent='ภาพเรดาร์บางส่วนโหลดไม่สำเร็จ พื้นที่ว่างอาจไม่มีข้อมูล';$('mapError').hidden=false;}});}const minutes=Math.max(0,Math.round((Date.now()/1000-frames.at(-1).time)/60));$('mapStatus').textContent=minutes>30?'ภาพล่าช้า '+minutes+' นาที':'ภาพล่าสุด '+timeLabel(frames.at(-1).time)+' น.';}
async function loadRadar(){if(radarBusy||!map)return;radarBusy=true;try{const d=await getJSON('https://api.rainviewer.com/public/weather-maps.json',4*60000);if(!d.radar?.past?.length)throw Error('No radar frames');if(!/^https:\/\/[a-z0-9.-]+\.rainviewer\.com$/.test(d.host))throw Error('Invalid host');stopPlay();radarHost=d.host;frames=d.radar.past.filter(f=>Number.isFinite(f.time)&&/^\/v2\/radar\/[a-zA-Z0-9_-]+$/.test(f.path));if(!frames.length)throw Error('No valid frames');$('timeSlider').max=frames.length-1;$('timeSlider').disabled=false;$('playBtn').disabled=false;$('latestBtn').disabled=false;$('firstFrame').textContent=timeLabel(frames[0].time)+' น.';$('lastFrame').textContent=timeLabel(frames.at(-1).time)+' น.';if(mode==='radar')$('mapError').hidden=true;displayFrame(frames.length-1);if(coverageLayer)coverageLayer.remove();coverageLayer=L.tileLayer(radarHost+'/v2/coverage/0/256/{z}/{x}/{y}/0/0_0.png',{opacity:.17,maxNativeZoom:7,maxZoom:18,zIndex:190});coverageLayer.on('tileerror',()=>{if(mode==='radar'){$('mapError').textContent='ไม่สามารถยืนยันความครอบคลุมเรดาร์ พื้นที่ว่างอาจไม่มีข้อมูล';$('mapError').hidden=false;}});updateCoverage();}catch(e){if(mode==='radar'){$('mapStatus').textContent='เรดาร์เชื่อมต่อไม่ได้';$('mapError').textContent=frames.length?'อัปเดตไม่สำเร็จ กำลังแสดงภาพเดิมตามเวลาที่ระบุ':'ยังไม่มีภาพเรดาร์จาก RainViewer · ดูเรดาร์กรมอุตุนิยมวิทยาจากลิงก์ใต้แผนที่';$('mapError').hidden=false;}}finally{radarBusy=false;}}
function updateCoverage(){if(!coverageLayer||!map)return;if(mode==='radar'&&$('coverageCheck').checked)coverageLayer.addTo(map);else coverageLayer.remove();}
const layerConfig={radar:{title:'ติดตามกลุ่มฝน',desc:'คลิกบนแผนที่เพื่อดูพยากรณ์ของพื้นที่',unit:'dBZ',legend:'ความเข้มสัญญาณฝน',labels:['15','35','55+'],gradient:'linear-gradient(to right,#88ddee,#00a3e0,#0077aa,#005588,#ffee00,#ffaa00,#ff4400,#ee0000,#990000)'},wind:{title:'การเคลื่อนที่ของอากาศ',desc:'ลูกศรชี้ทิศที่ลมพัดไป · ลมสูงจากพื้น 10 เมตร',unit:'กม./ชม.',legend:'ความเร็วลม',labels:['0','20','40+'],gradient:'linear-gradient(to right,#cde4cf,#67af93,#126c6a)'},temp:{title:'อุณหภูมิทั่วภูมิภาค',desc:'อุณหภูมิสูงจากพื้น 2 เมตร · ข้อมูลแบบจำลอง',unit:'°C',legend:'อุณหภูมิ',labels:['15','25','35+'],gradient:'linear-gradient(to right,#83bfd4,#d3e4aa,#f0cb75,#d78b5f)'},pressure:{title:'ความกดอากาศระดับน้ำทะเล',desc:'ค่ารายจุดจากแบบจำลอง · ไม่ใช่เส้นไอโซบาร์',unit:'hPa',legend:'ความกดอากาศ',labels:['1000','1010','1020'],gradient:'linear-gradient(to right,#c7dce8,#dbe9cb,#8baf78)'}};
function setLayer(next){mode=next;stopPlay();document.querySelectorAll('[data-layer]').forEach(b=>{b.classList.toggle('active',b.dataset.layer===mode);b.setAttribute('aria-pressed',b.dataset.layer===mode);});const c=layerConfig[mode];$('layerTitle').textContent=c.title;$('layerDescription').textContent=c.desc;$('legendTitle').textContent=c.legend;$('legendUnit').textContent=c.unit;$('colorScale').style.background=c.gradient;$('scaleLabels').innerHTML=c.labels.map(x=>'<span>'+x+'</span>').join('');document.querySelector('.info-kicker').textContent=mode==='radar'?'RAIN RADAR':'ATMOSPHERIC CONDITIONS';$('radarTimeline').hidden=mode!=='radar';$('modelCaption').hidden=mode==='radar';$('mapError').hidden=true;if(modelGroup)modelGroup.clearLayers();if(mode==='radar'){displayFrame(frameIndex);if(!frames.length)loadRadar();}else{if(radarLayer)radarLayer.remove();renderModel();if(!gridData.length)loadGrid();}updateCoverage();updateMapResolution();$('modelCaption').textContent=areaGrid?'จุดตัวอย่าง 3 × 3 จากแบบจำลอง · พื้นที่ใกล้กันอาจใช้กริดเดียวกัน':'ค่ารายจุดจากแบบจำลอง Open-Meteo · คลิกจุดเพื่อดูรายละเอียด';}
async function loadGrid(){if(gridBusy)return;gridBusy=true;const p=new URLSearchParams({latitude:cities.map(c=>c[1]).join(','),longitude:cities.map(c=>c[2]).join(','),current:mapFields,timezone:'Asia/Bangkok',forecast_days:1});try{const d=await getJSON('https://api.open-meteo.com/v1/forecast?'+p,14*60000);if(!Array.isArray(d)||d.length!==cities.length)throw Error('Invalid model response');gridData=d;renderRegions();if(areaGrid)await refreshAreaValues();if(mode!=='radar')renderModel();}catch(e){if(!gridData.length)$('regionGrid').innerHTML='<div class="loading-text">ข้อมูลภูมิภาคยังไม่พร้อม · กดโหลดใหม่เพื่อลองอีกครั้ง</div>';if(mode!=='radar'){$('mapStatus').textContent='เชื่อมต่อข้อมูลไม่ได้';$('mapError').textContent=gridData.length?'อัปเดตไม่สำเร็จ กำลังแสดงข้อมูลเดิม':'ยังไม่สามารถโหลดข้อมูลลมและความกดอากาศได้';$('mapError').hidden=false;}}finally{gridBusy=false;}}
function renderRegions(){$('regionGrid').innerHTML=regions.map(r=>{const c=gridData[r.idx]?.current;if(!c)return'';return`<article class="region-card"><h3>${r.title}</h3><div class="region-city">จุดตัวอย่าง · ${cities[r.idx][0]}</div><strong>${fmt(c.pressure_msl)} <small>hPa</small></strong><p class="region-wind">↗ ลมจาก${direction(c.wind_direction_10m)}</p><p>${fmt(c.wind_speed_10m,1)} กม./ชม. · ${fmt(c.temperature_2m)}°C</p><p>ข้อมูล ${timeLabel(c.time)} น.</p></article>`;}).join('');}
function renderModel(){if(!map||!modelGroup)return;modelGroup.clearLayers();modelGroup.addTo(map);if(!gridData.length){$('mapStatus').textContent='กำลังโหลดแบบจำลอง';return;}gridData.forEach((d,i)=>{const c=d.current;if(!c)return;const city=cities[i];let value,bg='#fff';if(mode==='wind')value=`<b class="wind-arrow" style="transform:rotate(${(c.wind_direction_10m+180)%360}deg)">↑</b>${fmt(c.wind_speed_10m)}<small>กม./ชม.</small>`;else if(mode==='temp'){value=fmt(c.temperature_2m)+'°';bg=c.temperature_2m>33?'#f7dbb9':c.temperature_2m>27?'#eeedc7':'#d7e9df';}else{value=fmt(c.pressure_msl);bg=c.pressure_msl<1005?'#dce9ef':c.pressure_msl>1015?'#d9e8cb':'#f1f4e9';}L.marker([city[1],city[2]],{icon:L.divIcon({className:'weather-pin',html:`<span style="background:${bg}">${value}</span>`,iconSize:[66,mode==='wind'?48:28],iconAnchor:[33,14]})}).addTo(modelGroup).bindTooltip(`${escapeHTML(city[0])} · ${timeLabel(c.time)} น.`).on('click',()=>selectCity(city,false));});$('mapStatus').textContent='แบบจำลอง '+timeLabel(gridData[0].current.time)+' น.';}
function showResults(results){$('searchResults').hidden=false;$('searchResults').replaceChildren();if(!results.length){$('searchResults').innerHTML='<p>ไม่พบพื้นที่ ลองใช้ชื่อภาษาอังกฤษ หรือเลือกจุดบนแผนที่</p>';return;}results.forEach(r=>{const b=document.createElement('button');b.type='button';b.textContent=r[0];const s=document.createElement('small');s.textContent=r[3]||'ประเทศไทย';b.append(s);b.onclick=()=>selectCity(r);$('searchResults').append(b);});}
let searchSeq=0;
async function search(e){e.preventDefault();const q=$('citySearch').value.trim();if(!q)return;const seq=++searchSeq;const coords=q.match(/^\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*$/);if(coords){const lat=Number(coords[1]),lon=Number(coords[2]);if(lat>=5.5&&lat<=21&&lon>=97&&lon<=106){selectCity(['พิกัดที่ค้นหา',lat,lon]);}else toast('พิกัดต้องอยู่ในประเทศไทยหรือใกล้เคียง');return;}const local=cities.filter(c=>c[0].includes(q)||q.includes(c[0]));if(q==='กรุงเทพ'||q.toLowerCase()==='bangkok'){showResults([cities[0]]);return;}if(local.length){showResults(local);return;}$('searchResults').hidden=false;$('searchResults').innerHTML='<p>กำลังค้นหา…</p>';try{const p=new URLSearchParams({name:q,count:10,language:'th',format:'json',countryCode:'TH'});const d=await getJSON('https://geocoding-api.open-meteo.com/v1/search?'+p,3600000);if(seq!==searchSeq)return;showResults((d.results||[]).filter(x=>x.country_code==='TH').map(x=>[x.name,x.latitude,x.longitude,[x.admin2,x.admin1].filter(Boolean).join(' · ')]));}catch(e){if(seq===searchSeq)$('searchResults').innerHTML='<p>ค้นหาไม่ได้ในขณะนี้ เลือกพื้นที่บนแผนที่ได้</p>';}}
