 document.querySelectorAll('[data-day]').forEach(card=>{card.classList.toggle('chosen',card.dataset.day===selectedDay);const choose=()=>{selectedDay=card.dataset.day;$('forecastDay').value=selectedDay;cursorIndex=0;renderDetailedForecast();$('detailSection').scrollIntoView({behavior:'smooth',block:'start'});};card.onclick=choose;card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}};});
