function valueAt(field,index){const n=weather?.hourly?.[field]?.[index];return Number.isFinite(n)?n:null;}
function valuesOf(field){return detailIndices.map(i=>valueAt(field,i));}
function fullSum(values){return values.length&&values.every(Number.isFinite)?values.reduce((a,b)=>a+b,0):null;}
function maxValue(values){const valid=values.filter(Number.isFinite);return valid.length?Math.max(...valid):null;}
