 $('modelGridNote').textContent=`จุดที่เลือก ${currentCity[1].toFixed(5)}, ${currentCity[2].toFixed(5)} · พิกัดกริดที่ API ส่งกลับ ${fmt(weather.latitude,4)}, ${fmt(weather.longitude,4)} · ความละเอียดแบบจำลองขึ้นอยู่กับแหล่งต้นทาง พื้นที่ใกล้กันอาจมีค่าเดียวกัน`;
 cursorIndex=Math.min(cursorIndex,detailIndices.length-1);$('chartCursor').max=detailIndices.length-1;$('chartCursor').value=cursorIndex;$('chartCursor').disabled=false;renderChart();renderHourInspector();
