function renderChart(){if(!detailIndices.length)return;const m=metricDefinitions[chartMetric],series=valuesOf(chartMetric),secondary=m.secondary?valuesOf(m.secondary):[],valid=[...series,...secondary].filter(Number.isFinite);$('chartHeading').textContent=m.name+' · '+m.unit;document.querySelectorAll('[data-chart]').forEach(b=>{b.classList.toggle('active',b.dataset.chart===chartMetric);b.setAttribute('aria-pressed',b.dataset.chart===chartMetric);});if(!valid.length){$('weatherChart').innerHTML='<p class="loading-text">ไม่มีข้อมูลสำหรับกราฟนี้</p>';$('chartStats').textContent='';return;}
 let low=Math.min(...valid),high=Math.max(...valid);$('chartStats').textContent=`ต่ำสุด ${fmt(low,1)} / สูงสุด ${fmt(high,1)} ${m.unit}`+(m.secondary?' · เส้นประ = ลมกระโชก':'');if(chartMetric==='relative_humidity_2m'){low=0;high=100;}else if(m.bars||chartMetric==='wind_speed_10m'){low=0;high=Math.max(high*1.1,1);}else{const pad=Math.max((high-low)*.15,chartMetric==='pressure_msl'?1:.5);low-=pad;high+=pad;}
 const w=1000,h=258,left=62,right=20,top=24,bottom=38,cw=w-left-right,ch=h-top-bottom;const x=n=>left+(n/Math.max(1,series.length-1))*cw,y=v=>top+(high-v)/(high-low)*ch;let content='';
 for(let k=0;k<=4;k++){const v=low+(high-low)*k/4,yp=y(v);content+=`<line x1="${left}" x2="${w-right}" y1="${yp}" y2="${yp}" stroke="#e7ede6"/><text x="${left-10}" y="${yp+4}" text-anchor="end" fill="#71816f" font-size="12">${fmt(v,1)}</text>`;}
 const labelIndices=[...new Set([0,Math.round((series.length-1)*.25),Math.round((series.length-1)*.5),Math.round((series.length-1)*.75),series.length-1])];for(const n of labelIndices){const t=weather.hourly.time[detailIndices[n]];content+=`<text x="${x(n)}" y="${h-10}" text-anchor="${n===0?'start':n===series.length-1?'end':'middle'}" fill="#71816f" font-size="12">${shortDate(t)} ${timeLabel(t)}</text>`;}
 if(m.bars){const bw=Math.max(3,cw/series.length*.62);series.forEach((v,n)=>{if(Number.isFinite(v))content+=`<rect x="${x(n)-bw/2}" y="${y(v)}" width="${bw}" height="${Math.max(0,y(0)-y(v))}" rx="2" fill="${m.color}" opacity=".8"/>`;});}else{const path=values=>{let d='',open=false;values.forEach((v,n)=>{if(Number.isFinite(v)){d+=(open?'L':'M')+x(n).toFixed(1)+','+y(v).toFixed(1)+' ';open=true;}else open=false;});return d;};content+=`<path d="${path(series)}" fill="none" stroke="${m.color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>`;if(secondary.length)content+=`<path d="${path(secondary)}" fill="none" stroke="#a5864c" stroke-width="2" stroke-dasharray="6 5"/>`;}
 content+=`<line id="chartCrosshair" x1="${x(cursorIndex)}" x2="${x(cursorIndex)}" y1="${top}" y2="${h-bottom}" stroke="#183d34" stroke-opacity=".5" stroke-dasharray="3 4"/>`;
 $('weatherChart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-labelledby="hourlyChartTitle"><title id="hourlyChartTitle">${m.name} ${m.unit} ดูค่าที่แน่นอนในตารางรายชั่วโมงด้านล่าง</title>${content}</svg>`;
}
function renderHourInspector(){if(!detailIndices.length||!weather)return;const i=detailIndices[cursorIndex];$('cursorTime').textContent=dateTime(weather.hourly.time[i]);$('hourInspector').innerHTML=`<strong>${icon(weather.hourly.weather_code[i])}${desc(weather.hourly.weather_code[i])}</strong><span>อุณหภูมิ <b>${fmt(valueAt('temperature_2m',i),1)}°</b></span><span>ฝน <b>${fmt(valueAt('precipitation',i),1)} มม.</b> / ${fmt(valueAt('precipitation_probability',i))}%</span><span>ความชื้น <b>${fmt(valueAt('relative_humidity_2m',i))}%</b></span><span>ลม / กระโชก <b>${fmt(valueAt('wind_speed_10m',i),1)} / ${fmt(valueAt('wind_gusts_10m',i),1)} กม./ชม.</b></span><span>ความกดอากาศ <b>${fmt(valueAt('pressure_msl',i),1)} hPa</b></span>`;const cross=$('chartCrosshair');if(cross){const x=62+cursorIndex/Math.max(1,detailIndices.length-1)*918;cross.setAttribute('x1',x);cross.setAttribute('x2',x);}document.querySelectorAll('[data-hour]').forEach(row=>row.classList.toggle('selected-hour',+row.dataset.hour===cursorIndex));}
function updateMapResolution(){if(!map)return;const zoom=map.getZoom();$('resolutionNote').textContent=mode==='radar'?(zoom>7?`ซูมแผนที่ระดับ ${zoom} · เรดาร์เป็นภาพขยายจากต้นทางระดับ 7 ไม่ได้เพิ่มความละเอียดฝน`:`ซูมแผนที่ระดับ ${zoom} · เรดาร์ต้นทางสูงสุดระดับ 7 · คลิกจุดเพื่อดูค่าพยากรณ์`):`ซูมแผนที่ระดับ ${zoom} · จุดข้อมูลจากกริดแบบจำลอง ไม่ใช่สถานีตรวจวัด · กดอ่านค่า 9 จุดเพื่อเทียบบริเวณนี้`;}
function markerForWeather(city,c,group){let value,bg='#fff';if(mode==='wind'){value=`<b class="wind-arrow" style="transform:rotate(${Number.isFinite(c.wind_direction_10m)?(c.wind_direction_10m+180)%360:0}deg)">↑</b>${fmt(c.wind_speed_10m)}<small>กม./ชม.</small>`;bg=c.wind_speed_10m>25?'#a9d4c5':'#e3f0e7';}else if(mode==='temp'){value=fmt(c.temperature_2m)+'°';bg=c.temperature_2m>33?'#f7dbb9':c.temperature_2m>27?'#eeedc7':'#d7e9df';}else if(mode==='pressure'){value=fmt(c.pressure_msl);bg=c.pressure_msl<1005?'#dce9ef':c.pressure_msl>1015?'#d9e8cb':'#f1f4e9';}else if(mode==='humidity'){value=fmt(c.relative_humidity_2m)+'%';bg=c.relative_humidity_2m>75?'#acd1db':'#e0ede2';}else if(mode==='cloud'){value=fmt(c.cloud_cover)+'%';bg=c.cloud_cover>70?'#c1cfd8':'#e9eff1';}else{value=fmt(c.precipitation,1)+'<small>มม./15 นาที</small>';bg=c.precipitation>1?'#acd1db':'#e1f1ee';}L.marker([city[1],city[2]],{icon:L.divIcon({className:'weather-pin',html:`<span style="background:${bg}">${value}</span>`,iconSize:[74,mode==='wind'||mode==='rain'?48:28],iconAnchor:[37,14]})}).addTo(group).bindTooltip(`${escapeHTML(city[0])} · ${dateTime(c.time)}`).on('click',()=>selectCity(city,false));}
function renderDetailedModel(){if(!map||!modelGroup)return;modelGroup.clearLayers();modelGroup.addTo(map);const source=areaGrid||gridData.map((data,i)=>({city:cities[i],data}));if(!source.length){$('mapStatus').textContent='กำลังโหลดแบบจำลอง';return;}source.forEach(p=>{if(p.data.current)markerForWeather(p.city,p.data.current,modelGroup);});$('mapStatus').textContent=(areaGrid?'9 จุด · ':'แบบจำลอง ')+timeLabel(source[0].data.current.time)+' น.';}
async function readAreaValues(){if(!map||areaLoading)return;if(Date.now()-lastAreaRead<30000){toast('รอ 30 วินาทีก่อนอ่านบริเวณใหม่ เพื่อลดการเรียก API');return;}const bounds=map.getBounds(),s=Math.max(bounds.getSouth(),5.5),n=Math.min(bounds.getNorth(),21),w=Math.max(bounds.getWest(),97),e=Math.min(bounds.getEast(),106);if(s>=n||w>=e){toast('เลื่อนแผนที่มาบริเวณประเทศไทยก่อน');return;}const points=[];for(const lat of [.2,.5,.8])for(const lon of [.2,.5,.8])points.push(['จุดตัวอย่าง '+(points.length+1),Number((s+(n-s)*lat).toFixed(5)),Number((w+(e-w)*lon).toFixed(5))]);areaLoading=true;const seq=++areaRequestId;lastAreaRead=Date.now();$('areaValues').disabled=true;$('areaValues').textContent='กำลังอ่านข้อมูล 9 จุด…';const p=new URLSearchParams({latitude:points.map(c=>c[1]).join(','),longitude:points.map(c=>c[2]).join(','),current:mapFields,timezone:'Asia/Bangkok',forecast_days:1});try{const d=await getJSON('https://api.open-meteo.com/v1/forecast?'+p,14*60000);if(seq!==areaRequestId)return;if(!Array.isArray(d)||d.length!==9||d.some(x=>!x.current))throw Error('Missing area grid');areaGrid=d.map((data,i)=>({city:points[i],data}));$('countryValues').hidden=false;setLayer(mode==='radar'?'rain':mode);toast('แสดงค่าจากแบบจำลอง 9 จุดแล้ว คลิกจุดเพื่อดูรายละเอียด');}catch(e){toast('โหลดข้อมูลบริเวณนี้ไม่ได้ กรุณาลองใหม่ภายหลัง');}finally{areaLoading=false;$('areaValues').disabled=false;$('areaValues').textContent='อ่านค่า 9 จุดในบริเวณนี้';}}
async function refreshAreaValues(){if(!areaGrid||areaLoading)return;const points=areaGrid.map(p=>p.city),seq=areaRequestId;const p=new URLSearchParams({latitude:points.map(c=>c[1]).join(','),longitude:points.map(c=>c[2]).join(','),current:mapFields,timezone:'Asia/Bangkok',forecast_days:1});try{const d=await getJSON('https://api.open-meteo.com/v1/forecast?'+p,14*60000);if(seq!==areaRequestId||!areaGrid)return;if(!Array.isArray(d)||d.length!==points.length||d.some(x=>!x.current))throw Error('Incomplete area refresh');areaGrid=d.map((data,i)=>({city:points[i],data}));}catch(e){if(seq===areaRequestId&&areaGrid){$('resolutionNote').textContent='อัปเดตจุดตัวอย่างไม่ได้ · กำลังแสดงข้อมูลเดิมตามเวลาที่ระบุ';}}}
function wireDetailControls(){
 $('forecastDay').onchange=e=>{selectedDay=e.target.value;cursorIndex=0;renderDetailedForecast();};$('hourWindow').onchange=e=>{hourWindow=Number(e.target.value);cursorIndex=0;renderDetailedForecast();};document.querySelectorAll('[data-chart]').forEach(b=>b.onclick=()=>{chartMetric=b.dataset.chart;renderChart();});$('chartCursor').oninput=e=>{cursorIndex=Number(e.target.value);renderHourInspector();};const inspectRow=e=>{const r=e.target.closest('[data-hour]');if(!r)return;cursorIndex=Number(r.dataset.hour);$('chartCursor').value=cursorIndex;renderHourInspector();};$('hourTableBody').onclick=inspectRow;$('hourTableBody').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspectRow(e);}};
 $('radarOpacity').oninput=e=>{radarOpacity=Number(e.target.value)/100;$('opacityValue').textContent=e.target.value+'%';radarLayer?.setOpacity(radarOpacity);};$('smoothRadar').onchange=()=>displayFrame(frameIndex);$('playSpeed').onchange=()=>{if(playing){stopPlay();$('playBtn').click();}};$('focusPoint').onclick=()=>{if(map)map.flyTo([currentCity[1],currentCity[2]],15,{duration:.6});};$('areaValues').onclick=readAreaValues;$('countryValues').onclick=()=>{areaRequestId++;areaGrid=null;$('countryValues').hidden=true;setLayer(mode==='radar'?'temp':mode);};$('expandMap').onclick=()=>{const panel=document.querySelector('.map-panel'),expanded=panel.classList.toggle('map-expanded');document.body.classList.toggle('map-is-expanded',expanded);$('expandMap').textContent=expanded?'ย่อแผนที่':'ขยายแผนที่';$('expandMap').setAttribute('aria-expanded',expanded);if(expanded&&!$('closeExpandedMap')){const b=document.createElement('button');b.id='closeExpandedMap';b.className='close-expanded-map';b.textContent='ย่อแผนที่ ×';b.onclick=()=>$('expandMap').click();panel.append(b);}if($('closeExpandedMap'))$('closeExpandedMap').hidden=!expanded;map?.invalidateSize();if(expanded)$('closeExpandedMap').focus();else $('expandMap').focus();};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.map-panel').classList.contains('map-expanded'))$('expandMap').click();});
}
renderModel=renderDetailedModel;

