document.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>selectCity(cities[+b.dataset.city]));document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{setLayer(b.dataset.layer);document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav===(mode==='radar'?'radar':'air')));});document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));$('viewAirBtn').onclick=()=>{navigate('air');document.querySelector('.map-panel').scrollIntoView({behavior:'smooth'});};$('searchForm').onsubmit=search;$('citySearch').oninput=()=>{searchSeq++;if(!$('citySearch').value)$('searchResults').hidden=true;};document.addEventListener('click',e=>{if(!e.target.closest('.location-box'))$('searchResults').hidden=true;});$('zoomIn').onclick=()=>map?.zoomIn();$('zoomOut').onclick=()=>map?.zoomOut();$('resetMap').onclick=()=>map?.fitBounds([[5.7,97.2],[20.5,105.7]],{padding:[38,38]});$('timeSlider').oninput=e=>{stopPlay();displayFrame(e.target.value);};$('latestBtn').onclick=()=>{stopPlay();displayFrame(frames.length-1);};$('playBtn').onclick=()=>{if(playing){stopPlay();return;}if(!frames.length)return;$('playBtn').textContent='Ⅱ';$('playBtn').setAttribute('aria-label','หยุดภาพเรดาร์');displayFrame((frameIndex+1)%frames.length);playing=setInterval(()=>displayFrame((frameIndex+1)%frames.length),Number($('playSpeed').value));};$('coverageCheck').onchange=updateCoverage;
let lastRefresh=0;$('refreshBtn').onclick=()=>{if(Date.now()-lastRefresh<30000){toast('รอสักครู่ก่อนโหลดใหม่ เพื่อลดการเรียก API');return;}lastRefresh=Date.now();if(weatherBusy||radarBusy||gridBusy){toast('กำลังโหลดข้อมูล โปรดรอสักครู่');return;}cache.clear();loadWeather(false);loadRadar();loadGrid();toast('กำลังอัปเดตข้อมูลจากแหล่งต้นทาง');};
$('locateBtn').onclick=()=>{if(!navigator.geolocation){toast('เบราว์เซอร์นี้ไม่รองรับตำแหน่ง');return;}toast('กำลังหาตำแหน่งของคุณ');navigator.geolocation.getCurrentPosition(p=>{const {latitude,longitude}=p.coords;if(latitude<5||latitude>21||longitude<97||longitude>106){toast('ตำแหน่งอยู่นอกประเทศไทย เลือกจังหวัดหรือจุดบนแผนที่ได้');return;}selectCity(['ตำแหน่งของฉัน',latitude,longitude]);},()=>toast('ไม่สามารถเข้าถึงตำแหน่งได้ เลือกจังหวัดหรือจุดบนแผนที่แทน'),{timeout:12000,maximumAge:300000});};
$('sourcesBtn').onclick=$('footerSources').onclick=()=>$('sourcesDialog').showModal();$('closeDialog').onclick=()=>$('sourcesDialog').close();$('sourcesDialog').onclick=e=>{if(e.target===$('sourcesDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
setInterval(()=>{if(!document.hidden)loadRadar();},300000);setInterval(()=>{if(!document.hidden){loadWeather(false);loadGrid();}},900000);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopPlay();else{loadRadar();loadWeather(false);loadGrid();}});window.addEventListener('offline',()=>{$('connectionStatus').textContent='ออฟไลน์ · แสดงข้อมูลที่โหลดไว้';toast('ออฟไลน์ ข้อมูลที่เห็นอาจไม่ใช่ข้อมูลล่าสุด');});window.addEventListener('online',()=>{loadWeather(false);loadRadar();loadGrid();});

